  const storedValue = (path,value) => Number(value)/(isPercentage(path)?100:1);
  function parseSymbols(value,max=50) {
    const tokens=String(value||'').trim().split(/[\s,，;；、]+/).filter(Boolean),symbols=[];
    for(const token of tokens){const code=token.toLowerCase();if(!/^(?:(?:sh|sz|bj))?\d{6}$/.test(code))throw new Error(`股票代码无效：${token}`);const normalized=/^(sh|sz|bj)/.test(code)?code:(/^(4|8|92)/.test(code)?'bj':/^[569]/.test(code)?'sh':'sz')+code;if(!symbols.includes(normalized))symbols.push(normalized);}
    if(!symbols.length)throw new Error('请填写至少一只股票代码。');if(symbols.length>max)throw new Error(`每个任务最多研究 ${max} 只股票。`);return symbols;
  }
