  const labels={initialCapital:'初始资金（元）',maxPositions:'最多持仓只数',positionFraction:'单股目标仓位（%）',maxParticipationRate:'成交量参与上限（%）',costMultiplier:'费用压力倍数',stopLossPct:'止损阈值（%）',takeProfitPct:'全部止盈阈值（%）',partialTakeProfitPct:'首次减仓阈值（%）',partialSellFraction:'首次卖出剩余仓位（%）',trailingStopPct:'移动止损（%）',maxHoldingDays:'最长持仓交易日',commissionRate:'佣金费率（%）',minCommission:'最低佣金（元）',stampDutyRate:'卖出印花税率（%，留空自动）',transferFeeRate:'过户费率（%）',slippageBps:'单边滑点（基点）'};
  const model={catalogue:null,tasks:[],details:new Map(),activeId:'',strategyId:'',error:'',feedback:'',loading:false,writing:false,selected:new Set(),filter:'all',pathQuery:'',pathOffset:0,dailyOffset:0,rotationOffset:0,resultPath:null,candidateId:'',sliceIndex:null,curveIndex:null,compareId:'',ready:false,taskQuery:'',renameId:'',renameName:'',deleteIds:[],eventDate:null};
  const draft={name:'',symbols:'',config:{},axes:[{path:'stopLossPct',values:'4, 6, 8'},{path:'takeProfitPct',values:'16, 20, 24'},{path:'',values:''}],holdoutFraction:20,folds:3,minTrades:3,maxDrawdownPct:30};
  let timer=null,requestId=0,pendingCreate=null;
  const pendingWrites=new Set(),detailRequests=new Map();
