  function strategyParameters(){return (model.catalogue?.strategies||[]).filter(s=>draft.config.strategyIds?.includes(s.id)).map(strategy=>`<fieldset class="rs-fieldset"><legend>${E(strategy.name)} · 策略参数</legend><div class="rs-fields">${(strategy.parameters||[]).map(p=>numericField(`strategyParams.${strategy.id}.${p.key}`,`${p.label}${isPercentage(p.key)?'（%）':''}`,draft.config.strategyParams?.[strategy.id]?.[p.key]??p.default,p)).join('')}</div></fieldset>`).join('');}
