  function axisOptions(){const common=['stopLossPct','takeProfitPct','partialTakeProfitPct','partialSellFraction','trailingStopPct','maxHoldingDays','maxPositions','positionFraction'].map(path=>({path,label:labels[path]}));for(const s of model.catalogue?.strategies||[])if(draft.config.strategyIds?.includes(s.id))for(const p of s.parameters||[])common.push({path:`strategyParams.${s.id}.${p.key}`,label:`${s.name} / ${p.label}${isPercentage(p.key)?'（%）':''}`});return common;}
  function scanForm(){const options=axisOptions();return `<fieldset class="rs-fieldset"><legend>参数范围与独立验证</legend>${draft.axes.map((axis,i)=>`<div class="rs-axis-row"><label class="rs-field"><span>扫描轴 ${i+1}${i===2?'（可选）':''}</span><select data-rs-axis-path="${i}"><option value="">不使用</option>${options.map(p=>`<option value="${E(p.path)}" ${axis.path===p.path?'selected':''}>${E(p.label)}</option>`).join('')}</select></label>${field('候选值（百分比项直接填写 % 数值）',`axis.${i}`,axis.values,'text','placeholder="例如：4, 6, 8"')}</div>`).join('')}<div class="rs-fields">${field('末段独立留出（%）','holdoutFraction',draft.holdoutFraction,'number','min="10" max="40" step="1" required')}${field('训练分块数','folds',draft.folds,'number','min="2" max="6" step="1" required')}${field('每块最少完整交易','minTrades',draft.minTrades,'number','min="1" step="1" required')}${field('最大允许回撤（%）','maxDrawdownPct',draft.maxDrawdownPct,'number','min="0.1" max="100" step="0.1" required')}</div><p class="rs-help">最多 ${n(model.catalogue?.limits?.maxCombinations||125,0)} 组。推荐只使用前段训练分块与邻域稳定性；末段留出只验收一次，失败不会换参挑选。相邻稳定区域优先于最高单点。</p></fieldset>`;}
  function strategyCards(details=false){const library=model.catalogue?.portfolio?.strategies||model.catalogue?.strategies||[];const list=details?library.filter(s=>s.id===(model.strategyId||library[0]?.id)):library;return `<div class="rs-strategies">${list.map(s=>`<article class="rs-panel rs-strategy"><span class="rs-eyebrow">${E(s.id)}</span><h2>${E(s.name)}</h2><p>${E(s.description||'')}</p>${s.rationale?`<h3>研究依据</h3><p>${E(Array.isArray(s.rationale)?s.rationale.join('；'):s.rationale)}</p>`:''}${s.caveats?notice(Array.isArray(s.caveats)?s.caveats.join('；'):s.caveats):''}${details?table(['参数','默认值','范围'],(s.parameters||[]).map(p=>`<tr><td>${E(p.label)}${isPercentage(p.key)?'（%）':''}</td><td>${n(displayValue(p.key,p.default))}</td><td>${n(displayValue(p.key,p.min))} — ${n(displayValue(p.key,p.max))}</td></tr>`)):''}<footer>${button('查看定义','strategy-detail',`data-rs-id="${E(s.id)}"`)}${button('配置回测','strategy-use',`data-rs-id="${E(s.id)}"`,true)}</footer></article>`).join('')||empty(model.loading?'正在读取策略定义…':'没有已注册的策略')}</div>`;}
  function controls(t){return allowedActions(t.status).map(action=>button(actionNames[action],'control',`data-rs-id="${E(t.id)}" data-rs-control="${action}" ${model.writing?'disabled':''}`)).join('');}
  const kindNames={plateau:'参数平原',backtest:'组合回测',portfolio:'股票池组合',comparison:'策略比较与持续性',walkForward:'滚动样本外验证',systemPlateau:'全系统平原',poolPreview:'股票池筛选预览',singleBacktest:'单策略固定参数回测',singlePlateau:'单策略关键参数平原',frozenValidation:'其他日期验证'};
