  const matchesTask=t=>(model.filter==='all'||t.status===model.filter)&&(!model.taskQuery||[t.name,t.id,kindNames[t.kind],t.config?.startDate,t.config?.endDate,...(t.symbols||[])].join(' ').toLowerCase().includes(model.taskQuery.toLowerCase()));
  function taskActions(t){return controls(t)+button('重命名','task-rename',`data-rs-id="${E(t.id)}" ${model.writing?'disabled':''}`)+(isPoolTask(t)&&t.kind!=='frozenValidation'?button(t.configEditable?'编辑参数':'复用设置','task-edit',`data-rs-id="${E(t.id)}"`)+button('复制配置','task-copy',`data-rs-id="${E(t.id)}"`):'')+button('删除记录','task-delete',`data-rs-id="${E(t.id)}" ${model.writing||['running','pausing','stopping'].includes(t.status)?'disabled':''}`);}
