  function phaseText(value){const fold=/^fold (\d+): (\w+)/.exec(value||'');if(fold)return `第 ${fold[1]} 折 · ${({training:'策略训练',oosCandidates:'样本外验证',baselines:'对照方案'})[fold[2]]||'计算中'}`;if(/^continuous/.test(value||''))return '连续资金账户计算中';const stage=/^(training|testing): (.+)/.exec(value||'');if(stage)return (stage[1]==='training'?'训练区':'样本外')+' · '+(model.catalogue?.strategies?.find(s=>s.id===stage[2])?.name||({equalWeight:'策略等权',fixed:'训练选定固定策略',softRotation:'动态软配权',hardRotation:'硬切换对照'})[stage[2]]||'策略组合');return /[\u3400-\u9fff]/.test(value||'')?value:recordLabels[value]||'后台计算中';}
